import { describe, expect, it } from 'vitest';
import hauntedMansion from './data/haunted-mansion';
import neonCity from './data/neon-city';
import spaceStation from './data/space-station';
import type { Course, Hole, SurfaceDescriptor } from './types';

/**
 * Guards the design rule that a course is a set of distinct layouts rather
 * than one straight corridor repeated nine times: every hole must turn or
 * branch, tees and cups must move around, and each course keeps a few
 * multi-level holes with an alternative route.
 */
const COURSES: Course[] = [neonCity, hauntedMansion, spaceStation];

const footprint = (surface: SurfaceDescriptor) => {
  const p = surface.transform.position;
  return {
    minX: p.x - surface.size.x / 2,
    maxX: p.x + surface.size.x / 2,
    minZ: p.z - surface.size.z / 2,
    maxZ: p.z + surface.size.z / 2,
    top: p.y + surface.size.y / 2,
  };
};

const covers = (surface: SurfaceDescriptor, x: number, z: number): boolean => {
  const f = footprint(surface);
  return x >= f.minX - 1e-6 && x <= f.maxX + 1e-6 && z >= f.minZ - 1e-6 && z <= f.maxZ + 1e-6;
};

/** Lateral spread of the floor slabs: a plain corridor keeps every slab on one axis. */
const lateralSpan = (hole: Hole): number => {
  const xs = hole.surfaces.map((surface) => surface.transform.position.x);
  return Math.max(...xs) - Math.min(...xs);
};

const elevations = (hole: Hole): Set<number> =>
  new Set(hole.surfaces.map((surface) => Number(surface.transform.position.y.toFixed(2))));

for (const course of COURSES) {
  describe(`${course.id} layouts`, () => {
    it('ships nine holes with unique ids', () => {
      expect(course.holes).toHaveLength(9);
      expect(new Set(course.holes.map((hole) => hole.id)).size).toBe(9);
    });

    it('builds every hole from more than one floor slab', () => {
      const single = course.holes.filter((hole) => hole.surfaces.length < 2).map((hole) => hole.id);
      expect(single).toEqual([]);
    });

    it('offsets the cup from the tee axis on nearly every hole', () => {
      const offset = course.holes.filter((hole) => Math.abs(hole.cup.position.x) >= 1);
      expect(offset.length).toBeGreaterThanOrEqual(8);
    });

    it('moves the tee around between holes', () => {
      const tees = new Set(course.holes.map((hole) => `${hole.spawn.x}:${hole.spawn.z}`));
      expect(tees.size).toBeGreaterThanOrEqual(5);
      expect(new Set(course.holes.map((hole) => hole.spawn.x)).size).toBeGreaterThanOrEqual(4);
    });

    it('never lays a hole out as a single straight corridor', () => {
      const straight = course.holes.filter((hole) => lateralSpan(hole) < 3).map((hole) => hole.id);
      expect(straight).toEqual([]);
    });

    it('keeps several multi-level holes with ramps', () => {
      const layered = course.holes.filter((hole) => elevations(hole).size > 1);
      expect(layered.length).toBeGreaterThanOrEqual(3);
      const ramped = course.holes.filter((hole) =>
        hole.surfaces.some((surface) => surface.shape === 'ramp'),
      );
      expect(ramped.length).toBeGreaterThanOrEqual(2);
    });

    it('offers alternative routes on most holes', () => {
      const branching = course.holes.filter((hole) => hole.surfaces.length >= 4);
      expect(branching.length).toBeGreaterThanOrEqual(5);
    });

    it('keeps tee and cup on a slab and inside the hole bounds', () => {
      for (const hole of course.holes) {
        const cupSlab = hole.surfaces.find(
          (surface) =>
            covers(surface, hole.cup.position.x, hole.cup.position.z) &&
            Math.abs(footprint(surface).top - hole.cup.position.y) < 0.2,
        );
        expect(cupSlab, `${hole.id}: cup must rest on a slab`).toBeDefined();

        const teeSlab = hole.surfaces.find((surface) => {
          if (!covers(surface, hole.spawn.x, hole.spawn.z)) return false;
          const clearance = hole.spawn.y - footprint(surface).top;
          return clearance > 0 && clearance < 0.6;
        });
        expect(teeSlab, `${hole.id}: tee must sit above a slab`).toBeDefined();

        for (const point of [hole.spawn, hole.cup.position]) {
          expect(point.x).toBeGreaterThanOrEqual(hole.bounds.min.x);
          expect(point.x).toBeLessThanOrEqual(hole.bounds.max.x);
          expect(point.y).toBeGreaterThanOrEqual(hole.bounds.min.y);
          expect(point.y).toBeLessThanOrEqual(hole.bounds.max.y);
          expect(point.z).toBeGreaterThanOrEqual(hole.bounds.min.z);
          expect(point.z).toBeLessThanOrEqual(hole.bounds.max.z);
        }
      }
    });
  });
}

describe('course pack', () => {
  it('does not repeat one layout across the three themed courses', () => {
    const signatures = COURSES.flatMap((course) =>
      course.holes.map((hole) =>
        hole.surfaces
          .map((surface) => `${surface.transform.position.x}/${surface.transform.position.z}/${surface.size.x}x${surface.size.z}`)
          .join('|'),
      ),
    );
    expect(new Set(signatures).size).toBe(signatures.length);
  });
});
